fun cyclicSort(nums: IntArray) {
    var i = 0
    while (i < nums.size) {
        val correct = nums[i] - 1            // home index of nums[i]
        if (nums[i] != nums[correct]) {
            // swap nums[i] with nums[correct]
            val tmp = nums[i]
            nums[i] = nums[correct]
            nums[correct] = tmp
        } else {
            i++                              // already home or duplicate
        }
    }
}
// Time: O(n)   Space: O(1)

fun cyclicSortSafe(nums: IntArray) {
    val n = nums.size
    var i = 0
    while (i < n) {
        val correct = nums[i] - 1
        // only swap if the value is in range 1..n and not already placed
        if (nums[i] in 1..n && nums[i] != nums[correct]) {
            val tmp = nums[i]
            nums[i] = nums[correct]
            nums[correct] = tmp
        } else {
            i++
        }
    }
}
// Use this when values can be zero, negative or larger than n

fun missingNumber(nums: IntArray): Int {
    val n = nums.size
    var i = 0
    while (i < n) {
        val correct = nums[i]
        if (correct < n && nums[i] != nums[correct]) {
            val tmp = nums[i]; nums[i] = nums[correct]; nums[correct] = tmp
        } else {
            i++
        }
    }
    for (j in 0 until n) {
        if (nums[j] != j) return j
    }
    return n
}
// Time: O(n)   Space: O(1)
// Math alternative: n * (n + 1) / 2 - nums.sum()

fun findDisappearedNumbers(nums: IntArray): List<Int> {
    var i = 0
    while (i < nums.size) {
        val correct = nums[i] - 1
        if (nums[i] != nums[correct]) {
            val tmp = nums[i]; nums[i] = nums[correct]; nums[correct] = tmp
        } else {
            i++
        }
    }
    val missing = mutableListOf<Int>()
    for (j in nums.indices) {
        if (nums[j] != j + 1) missing.add(j + 1)
    }
    return missing
}
// Time: O(n)   Space: O(1) extra (output not counted)

fun findDuplicate(nums: IntArray): Int {
    var i = 0
    while (i < nums.size) {
        if (nums[i] != i + 1) {
            val correct = nums[i] - 1
            if (nums[i] != nums[correct]) {
                val tmp = nums[i]; nums[i] = nums[correct]; nums[correct] = tmp
            } else {
                return nums[i]            // value is already home elsewhere
            }
        } else {
            i++
        }
    }
    return -1
}
// Time: O(n)   Space: O(1)
// Modifies the array. For a read-only array use Fast & Slow Pointers

fun findDuplicates(nums: IntArray): List<Int> {
    var i = 0
    while (i < nums.size) {
        val correct = nums[i] - 1
        if (nums[i] != nums[correct]) {
            val tmp = nums[i]; nums[i] = nums[correct]; nums[correct] = tmp
        } else {
            i++
        }
    }
    val duplicates = mutableListOf<Int>()
    for (j in nums.indices) {
        if (nums[j] != j + 1) duplicates.add(nums[j])
    }
    return duplicates
}
// Time: O(n)   Space: O(1) extra

fun firstMissingPositive(nums: IntArray): Int {
    val n = nums.size
    var i = 0
    while (i < n) {
        val correct = nums[i] - 1
        if (nums[i] in 1..n && nums[i] != nums[correct]) {
            val tmp = nums[i]; nums[i] = nums[correct]; nums[correct] = tmp
        } else {
            i++
        }
    }
    for (j in 0 until n) {
        if (nums[j] != j + 1) return j + 1
    }
    return n + 1
}
// Time: O(n)   Space: O(1)
// The answer is always in the range 1..n + 1

fun findErrorNums(nums: IntArray): IntArray {
    var i = 0
    while (i < nums.size) {
        val correct = nums[i] - 1
        if (nums[i] != nums[correct]) {
            val tmp = nums[i]; nums[i] = nums[correct]; nums[correct] = tmp
        } else {
            i++
        }
    }
    for (j in nums.indices) {
        if (nums[j] != j + 1) {
            return intArrayOf(nums[j], j + 1)     // [duplicate, missing]
        }
    }
    return intArrayOf(-1, -1)
}
// Time: O(n)   Space: O(1)

fun firstMissingPositiveMark(nums: IntArray): Int {
    val n = nums.size
    // 1. Replace non-positive and too-large numbers with n + 1
    for (i in nums.indices) {
        if (nums[i] <= 0 || nums[i] > n) nums[i] = n + 1
    }
    // 2. Mark presence by making nums[value - 1] negative
    for (i in nums.indices) {
        val v = Math.abs(nums[i])
        if (v <= n && nums[v - 1] > 0) nums[v - 1] = -nums[v - 1]
    }
    // 3. First positive index means that number is missing
    for (i in nums.indices) {
        if (nums[i] > 0) return i + 1
    }
    return n + 1
}
// Time: O(n)   Space: O(1)
// Another O(1) space way to reach the same result

